<template>
  <PlatformAdminShell title="用户与权限" description="为创作者开通独立账号。每个人的项目、素材和任务各自保存。">
    <template #actions><button class="btn" @click="load" :disabled="loading"><RefreshCw :size="13" :class="{ 'animate-spin': loading }" />刷新</button><button class="btn btn-primary" @click="createOpen = true" :disabled="working !== null"><Plus :size="14" />添加用户</button></template>
    <div class="user-overview"><div><Users :size="18" /><span>全部账号<strong>{{ users.length }}</strong></span></div><div><UserCheck :size="18" /><span>已启用<strong>{{ users.filter(user => user.enabled).length }}</strong></span></div><div><ShieldCheck :size="18" /><span>管理员<strong>{{ users.filter(user => user.role === 'admin').length }}</strong></span></div></div>
    <section class="card user-table-card"><div class="user-table-toolbar"><label class="user-search"><Search :size="14" /><input v-model="search" placeholder="搜索用户名或显示名称" /></label><span>{{ filtered.length }} 个账号</span></div><div v-if="error" class="user-page-error" role="alert">{{ error }}</div><div v-if="loading && !users.length" class="user-empty"><Loader2 :size="22" class="animate-spin" /><p>正在读取用户…</p></div><div class="table-scroll" v-else><table class="user-table"><thead><tr><th>账号</th><th>角色</th><th>状态</th><th>创建时间</th><th>操作</th></tr></thead><tbody><tr v-for="user in filtered" :key="user.id"><td><div class="user-name"><span class="user-mini-avatar">{{ (user.displayName || user.display_name || user.username).slice(0,1) }}</span><span><strong :title="user.displayName || user.display_name || user.username">{{ user.displayName || user.display_name || user.username }}</strong><small :title="user.username">@{{ user.username }}<i v-if="user.id === selfId">当前账号</i></small></span></div></td><td><span :class="['role-chip',{admin:user.role==='admin'}]">{{ user.role === 'admin' ? '管理员' : '创作者' }}</span></td><td><span :class="['user-state',{disabled:!user.enabled}]"><i></i>{{ user.enabled ? '已启用' : '已停用' }}</span></td><td class="date-cell">{{ formatTime(user.createdAt || user.created_at) }}</td><td><div class="user-row-actions"><button class="btn btn-sm" @click="reset(user)" :disabled="working !== null"><KeyRound :size="12" />重置密码</button><button v-if="user.id !== selfId" :class="['btn','btn-sm',user.enabled && 'danger-link']" @click="toggle(user)" :disabled="working !== null">{{ user.enabled ? '停用' : '启用' }}</button><button v-if="!isSelf(user)" class="btn btn-sm danger-link" :disabled="working !== null || !canDeleteUser(user)" :title="deleteDisabledReason(user)" :aria-label="`删除用户 ${user.username}`" @click="requestDeleteUser(user)"><Trash2 :size="12" />删除</button></div></td></tr></tbody></table><div v-if="!filtered.length" class="user-empty"><Users :size="25" /><p>{{ search ? '没有匹配的账号' : '暂无用户' }}</p></div></div><footer class="user-table-footer"><ShieldCheck :size="13" />停用或删除账号后，用户无法继续登录或提交新任务；项目、素材和历史记录均保留。</footer></section>
    <div v-if="createOpen" class="overlay" @click.self="createOpen = false"><section class="dialog user-dialog" role="dialog" aria-modal="true" aria-labelledby="create-user-title"><header><div><h2 id="create-user-title">添加创作者</h2><p>创建独立登录身份，项目默认仅本人可见。</p></div><button class="btn btn-icon" @click="createOpen = false" aria-label="关闭"><X :size="17" /></button></header><form @submit.prevent="create"><label>用户名<input v-model.trim="form.username" class="input" autocomplete="off" required placeholder="例如 studio_01" /></label><label>显示名称<input v-model.trim="form.display_name" class="input" maxlength="80" placeholder="例如 剪辑同事 A" /></label><label>初始密码<span>留空由系统生成临时密码</span><input v-model="form.password" class="input" type="password" autocomplete="new-password" placeholder="输入初始密码，或留空自动生成" /></label><p v-if="createError" class="user-page-error" role="alert">{{ createError }}</p><footer><button type="button" class="btn" @click="createOpen = false">取消</button><button class="btn btn-primary" :disabled="creating"><Loader2 v-if="creating" :size="13" class="animate-spin" />{{ creating ? '正在创建…' : '创建账号' }}</button></footer></form></section></div>
    <div v-if="deleteTarget" class="overlay" @click.self="closeDeleteUser" @keydown.esc.stop.prevent="closeDeleteUser">
      <section ref="deleteDialog" class="dialog delete-user-dialog" role="alertdialog" aria-modal="true" aria-labelledby="delete-user-title" tabindex="-1">
        <div class="delete-user-icon"><Trash2 :size="24" /></div>
        <h2 id="delete-user-title">删除用户账号</h2>
        <p>确定删除 <strong>{{ deleteTarget.displayName || deleteTarget.display_name || deleteTarget.username }}</strong>（@{{ deleteTarget.username }}）？</p>
        <ul><li>账号将从用户列表移除，现有登录会话立即失效。</li><li>项目、素材、任务及历史记录保留，由管理员管理。</li><li>以后同名创建的是新账号，不会自动继承原资料。</li></ul>
        <p v-if="deleteError" class="user-page-error" role="alert">{{ deleteError }}</p>
        <footer><button type="button" class="btn" :disabled="working !== null" @click="closeDeleteUser">取消</button><button type="button" class="btn confirm-user-delete" :disabled="working !== null" @click="confirmDeleteUser"><Loader2 v-if="working !== null" :size="13" class="animate-spin" />{{ working !== null ? '正在删除…' : '删除账号' }}</button></footer>
      </section>
    </div>
    <div v-if="credential" class="overlay" @click.self="credential = null"><section class="dialog credential-dialog" role="dialog" aria-modal="true"><div class="credential-icon"><KeyRound :size="24" /></div><h2>{{ credential.title }}</h2><p>请将登录信息通过你信任的方式交给本人，提醒登录后修改密码。</p><label>用户名<strong>{{ credential.username }}</strong></label><label>初始密码<code>{{ credential.password }}</code></label><p class="credential-note">密码只在本次操作结果中显示，不会保存在浏览器缓存。</p><div><button class="btn" @click="copyCredential"><Copy :size="13" />复制登录信息</button><button class="btn btn-primary" @click="credential = null">已妥善保存</button></div></section></div>
  </PlatformAdminShell>
</template>
<script setup>
import { computed, onMounted, onBeforeUnmount, nextTick, reactive, ref } from 'vue'
import { Users, UserCheck, ShieldCheck, RefreshCw, Plus, Search, Loader2, KeyRound, X, Copy, Trash2 } from 'lucide-vue-next'
import { toast } from 'vue-sonner'
import PlatformAdminShell from '~/components/PlatformAdminShell.vue'
import { platformUserAPI } from '~/composables/useApi'
import { platformSession } from '~/utils/platform-session'
const users=ref([]),loading=ref(false),error=ref(''),search=ref(''),working=ref(null),createOpen=ref(false),creating=ref(false),createError=ref(''),credential=ref(null)
const deleteTarget=ref(null),deleteError=ref(''),deleteDialog=ref(null)
const form=reactive({username:'',display_name:'',password:''}),selfId=computed(()=>platformSession.user?.id)
const filtered=computed(()=>users.value.filter(u=>`${u.username} ${u.displayName||u.display_name||''}`.toLowerCase().includes(search.value.toLowerCase())))
let alive=true,listRevision=0,returnFocus=null
const current=revision=>alive&&platformSession.revision===revision
function isSelf(user){return Number(user.id)===Number(selfId.value)}
function canDeleteUser(user){return !isSelf(user)&&!(user.role==='admin'&&user.enabled&&users.value.filter(item=>item.role==='admin'&&item.enabled).length<=1)}
function deleteDisabledReason(user){return isSelf(user)?'不能删除当前登录账号':canDeleteUser(user)?'删除账号，保留项目和历史':'不能删除最后一个已启用的管理员'}
function formatTime(value){if(!value)return '—';const date=new Date(value);return Number.isNaN(date.getTime())?'—':date.toLocaleString('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'})}
async function load(){
  const turn=++listRevision,identity=platformSession.revision
  loading.value=true;error.value=''
  try{const value=await platformUserAPI.list();if(current(identity)&&turn===listRevision)users.value=Array.isArray(value)?value:value.users||value.items||[]}
  catch(e){if(current(identity)&&turn===listRevision)error.value=e.message}
  finally{if(current(identity)&&turn===listRevision)loading.value=false}
}
async function create(){if(creating.value||working.value!==null)return;if(!form.username.trim()){createError.value='请输入用户名。';return}creating.value=true;createError.value='';const identity=platformSession.revision;try{const result=await platformUserAPI.create({username:form.username.trim(),...(form.display_name.trim()?{display_name:form.display_name.trim()}:{}),password:form.password||undefined});if(!current(identity))return;createOpen.value=false;const password=result.temporary_password||form.password;if(password)credential.value={title:'账号已创建',username:result.user?.username||form.username,password};Object.assign(form,{username:'',display_name:'',password:''});await load();toast.success('创作者账号已创建')}catch(e){if(current(identity))createError.value=e.message}finally{if(current(identity))creating.value=false}}
async function toggle(user){if(working.value!==null)return;if(user.enabled&&!window.confirm(`停用 ${user.username} 的登录与新任务权限？项目和历史将保留。`))return;working.value=user.id;const identity=platformSession.revision;try{await platformUserAPI.update(user.id,{enabled:!user.enabled});if(!current(identity))return;await load();toast.success(user.enabled?'账号已停用':'账号已启用')}catch(e){if(current(identity))toast.error(e.message)}finally{if(current(identity))working.value=null}}
async function reset(user){if(working.value!==null)return;if(!window.confirm(`为 ${user.username} 重置密码？旧登录会话可能需要重新登录。`))return;working.value=user.id;const identity=platformSession.revision;try{const result=await platformUserAPI.resetPassword(user.id);if(!current(identity))return;if(result.temporary_password)credential.value={title:'密码已重置',username:user.username,password:result.temporary_password};else toast.success('密码已重置');await load()}catch(e){if(current(identity))toast.error(e.message)}finally{if(current(identity))working.value=null}}
function requestDeleteUser(user){
  if(working.value!==null||loading.value||!canDeleteUser(user))return
  deleteTarget.value={...user};deleteError.value=''
  returnFocus=typeof document==='undefined'?null:document.activeElement
  void nextTick(()=>deleteDialog.value?.focus?.({preventScroll:true}))
}
function closeDeleteUser(){if(working.value!==null)return;deleteTarget.value=null;deleteError.value='';returnFocus?.focus?.({preventScroll:true});returnFocus=null}
async function confirmDeleteUser(){
  const target=deleteTarget.value
  if(!target||working.value!==null)return
  const fresh=users.value.find(user=>Number(user.id)===Number(target.id))
  if(!fresh||!canDeleteUser(fresh)){deleteError.value='账号状态已变化，请刷新后再操作。';return}
  const identity=platformSession.revision
  working.value=target.id;deleteError.value='';listRevision++;loading.value=false
  try{
    const result=await platformUserAPI.remove(Number(target.id))
    if(!current(identity))return
    if(result?.deleted!==true||Number(result.user_id)!==Number(target.id))throw Error('删除结果不匹配，请刷新用户列表核对。')
    users.value=users.value.filter(user=>Number(user.id)!==Number(target.id))
    deleteTarget.value=null;returnFocus?.focus?.({preventScroll:true});returnFocus=null
    toast.success('用户账号已删除，项目和历史记录已保留')
    await load()
  }catch(e){if(current(identity))deleteError.value=e.message||'删除未完成，请重试。'}
  finally{if(current(identity))working.value=null}
}
async function copyCredential(){try{await navigator.clipboard.writeText(`用户名：${credential.value.username}\n初始密码：${credential.value.password}`);toast.success('登录信息已复制')}catch{toast.error('复制失败，请手动选择内容复制。')}}
onMounted(load)
onBeforeUnmount(()=>{alive=false;listRevision++;credential.value=null;deleteTarget.value=null})
</script>
<style scoped>
.user-overview{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;margin-bottom:22px}.user-overview>div{display:flex;align-items:center;gap:13px;background:var(--bg-1);border:1px solid var(--border);border-radius:13px;padding:19px 22px;color:var(--text-3)}.user-overview>div>svg{color:var(--accent-text);opacity:.75}.user-overview span{display:flex;align-items:baseline;justify-content:space-between;flex:1;font-size:12px}.user-overview strong{font-size:25px;color:var(--text-0);font-variant-numeric:tabular-nums}.user-table-card{overflow:hidden}.user-table-toolbar{display:flex;align-items:center;justify-content:space-between;padding:18px 20px;border-bottom:1px solid var(--border);gap:15px}.user-search{display:flex;align-items:center;gap:9px;color:var(--text-3)}.user-search input{background:none;border:0;outline:0;color:var(--text-1);font-size:12px;min-width:230px}.user-table-toolbar>span{font-size:11px;color:var(--text-3)}.table-scroll{overflow:auto}.user-table{width:100%;border-collapse:collapse;white-space:nowrap;font-size:12px}.user-table th{font-weight:500;color:var(--text-3);font-size:10px;text-align:left;background:var(--bg-0);padding:12px 20px}.user-table td{padding:18px 20px;border-top:1px solid var(--border)}.user-name{max-width:310px;min-width:0;display:flex;align-items:center;gap:11px}.user-mini-avatar{display:grid;place-items:center;width:35px;height:35px;border-radius:11px;background:var(--bg-2);color:var(--text-2);font-size:14px}.user-name>span:last-child{min-width:0;flex:1}.user-name strong{display:block;max-width:245px;overflow:hidden;text-overflow:ellipsis;font-size:12px;font-weight:600}.user-name small{max-width:245px;overflow:hidden;text-overflow:ellipsis;display:block;margin-top:5px;font-size:10px;color:var(--text-3)}.user-name i{font-style:normal;background:var(--accent-bg);color:var(--accent-text);font-size:9px;border-radius:4px;padding:2px 5px;margin-left:7px}.role-chip{background:var(--bg-2);padding:4px 7px;border-radius:5px;font-size:10px;color:var(--text-2)}.role-chip.admin{background:var(--accent-bg);color:var(--accent-text)}.user-state{display:inline-flex;align-items:center;gap:6px;font-size:11px;color:var(--success)}.user-state i{height:5px;width:5px;background:currentColor;border-radius:50%}.user-state.disabled{color:var(--text-3)}.date-cell{color:var(--text-3);font-size:11px}.user-row-actions{display:flex;gap:6px}.danger-link{color:var(--error);background:var(--error-bg)}.user-table-footer{padding:15px 20px;background:var(--bg-0);border-top:1px solid var(--border);color:var(--text-3);font-size:10px;display:flex;align-items:center;gap:7px;line-height:1.6}.user-empty{padding:55px;text-align:center;color:var(--text-3)}.user-empty svg{margin:auto}.user-empty p{margin-top:12px;font-size:12px}.user-page-error{font-size:12px;color:var(--error);line-height:1.7;padding:11px 14px;background:var(--error-bg);border-radius:8px;margin:12px}.user-dialog{width:440px;max-width:calc(100vw - 32px)}.user-dialog>header{padding:22px 24px;border-bottom:1px solid var(--border);display:flex;justify-content:space-between;align-items:flex-start}.user-dialog h2,.credential-dialog h2{font-size:18px}.user-dialog header p{margin-top:8px;font-size:11px;color:var(--text-3)}.user-dialog form{display:grid;gap:18px;padding:23px 24px}.user-dialog label{display:grid;gap:8px;font-size:12px;font-weight:600}.user-dialog label span{font-size:10px;font-weight:400;color:var(--text-3)}.user-dialog footer{display:flex;justify-content:flex-end;gap:8px;padding-top:6px}.credential-dialog{padding:30px;max-width:440px;width:calc(100vw - 32px)}.credential-icon{height:50px;width:50px;border-radius:16px;color:var(--accent-text);background:var(--accent-bg);display:grid;place-items:center;margin-bottom:20px}.credential-dialog>p{font-size:12px;color:var(--text-3);line-height:1.8;margin-top:10px}.credential-dialog label{display:grid;gap:8px;margin-top:20px;font-size:10px;color:var(--text-3)}.credential-dialog label strong,.credential-dialog code{font-size:14px;color:var(--text-0);padding:12px;background:var(--bg-2);border-radius:8px;overflow-wrap:anywhere}.credential-dialog .credential-note{font-size:10px;margin:18px 0}.credential-dialog>div:last-child{display:flex;gap:8px;justify-content:flex-end}@media(max-width:650px){.user-overview{gap:8px}.user-overview>div{padding:14px;gap:7px}.user-overview>div>svg{display:none}.user-overview span{font-size:10px}.user-overview strong{font-size:21px}.user-search input{min-width:0;width:180px}}
.delete-user-dialog{width:450px;max-width:calc(100vw - 32px);padding:28px;outline:none}.delete-user-icon{width:47px;height:47px;border-radius:14px;background:var(--error-bg);color:var(--error);display:grid;place-items:center;margin-bottom:16px}.delete-user-dialog h2{font-size:19px;margin-bottom:12px}.delete-user-dialog>p{font-size:12px;line-height:1.85;color:var(--text-2);overflow-wrap:anywhere}.delete-user-dialog ul{padding-left:19px;margin:13px 0;color:var(--text-3);font-size:11px;line-height:1.9}.delete-user-dialog footer{display:flex;justify-content:flex-end;gap:8px;margin-top:21px}.confirm-user-delete{background:var(--error);color:white}.delete-user-dialog .user-page-error{margin:12px 0 0}.confirm-user-delete:hover{background:var(--error);filter:brightness(.94)}
</style>
